00010 static void add_unique_path(std::vector<std::filesystem::path> &paths, const std::filesystem::path &path)
00011 {
00012     if (path.empty())
00013         return;
00014     if (std::find(paths.begin(), paths.end(), path) == paths.end())
00015         paths.push_back(path);
00016 }
