00018 static void find_common_paths(const std::vector<std::filesystem::path> &paths, std::vector<std::filesystem::path> &source_dirs)
00019 {
00020     if (paths.empty())
00021         return;
00022 
00023     add_unique_path(source_dirs, paths[0].parent_path());
00024 
00025     for (auto path_it = paths.begin() + 1; path_it != paths.end(); ++path_it)
00026     {
00027         // Only consider files that do actually exist
00028         if (!std::filesystem::exists(*path_it))
00029             continue;
00030 
00031         std::filesystem::path common_path;
00032         std::filesystem::path file_directory = path_it->parent_path();
00033         for (auto dir_it = source_dirs.begin(); dir_it != source_dirs.end(); ++dir_it)
00034         {
00035             common_path.clear();
00036             for (auto it2 = file_directory.begin(), it3 = dir_it->begin(); it2 != file_directory.end() && it3 != dir_it->end() && *it2 == *it3; ++it2, ++it3)
00037                 common_path /= *it2;
00038             if (!common_path.empty())
00039                 *dir_it = common_path;
00040         }
00041 
00042         if (!common_path.empty() && !file_directory.empty())
00043             add_unique_path(source_dirs, file_directory);
00044     }
00045 }
