00280 bool blink::application::read_debug_info(const BYTE *image_base)
00281 {
00282     struct RSDS_DEBUG_FORMAT
00283     {
00284         uint32_t signature;
00285         guid guid;
00286         uint32_t age;
00287         char path[1];
00288     } const *debug_data = nullptr;
00289 
00290     const auto headers = reinterpret_cast<const IMAGE_NT_HEADERS *>(
00291         image_base + reinterpret_cast<const IMAGE_DOS_HEADER *>(image_base)->e_lfanew);
00292 
00293     // Search debug directory for program debug database file name
00294     const IMAGE_DATA_DIRECTORY &debug_directory = headers->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_DEBUG];
00295     const auto debug_directory_entries = reinterpret_cast<const IMAGE_DEBUG_DIRECTORY *>(
00296         image_base + debug_directory.VirtualAddress);
00297 
00298     for (unsigned int i = 0; i < debug_directory.Size / sizeof(IMAGE_DEBUG_DIRECTORY); ++i)
00299     {
00300         if (debug_directory_entries[i].Type == IMAGE_DEBUG_TYPE_CODEVIEW)
00301         {
00302             debug_data = reinterpret_cast<const RSDS_DEBUG_FORMAT *>(
00303                 image_base + debug_directory_entries[i].AddressOfRawData);
00304             if (debug_data->signature == 0x53445352) // RSDS
00305                 break;
00306         }
00307     }
00308 
00309     if (debug_data == nullptr)
00310         return false;
00311 
00312     pdb_reader pdb(debug_data->path);
00313 
00314     // Check if the debug information actually matches the executable
00315     if (pdb.guid() != debug_data->guid)
00316         return false;
00317 
00318     print("  Found program debug database: " + std::string(debug_data->path));
00319 
00320     // The linker working directory should equal the project root directory
00321     std::string linker_cmd;
00322     std::filesystem::path cwd;
00323     pdb.read_link_info(cwd, linker_cmd);
00324     if (!cwd.empty())
00325         add_unique_path(_source_dirs, cwd);
00326 
00327     pdb.read_symbol_table(_image_base, _symbols);
00328     pdb.read_object_files(_object_files);
00329     pdb.read_source_files(_source_files, _source_file_map);
00330 
00331     return true;
00332 }
00333 void blink::application::read_import_address_table(const BYTE *image_base)
00334 {
00335     const auto headers = reinterpret_cast<const IMAGE_NT_HEADERS *>(
00336         _image_base + reinterpret_cast<const IMAGE_DOS_HEADER *>(_image_base)->e_lfanew);
00337 
00338     // Search import directory for additional symbols
00339     const IMAGE_DATA_DIRECTORY &import_directory = headers->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_IMPORT];
00340     const auto import_directory_entries = reinterpret_cast<const IMAGE_IMPORT_DESCRIPTOR *>(_image_base + import_directory.VirtualAddress);
00341 
00342     for (unsigned int i = 0; import_directory_entries[i].FirstThunk != 0; i++)
00343     {
00344         const auto name = reinterpret_cast<const char *>(_image_base + import_directory_entries[i].Name);
00345         const auto import_name_table = reinterpret_cast<const IMAGE_THUNK_DATA *>(_image_base + import_directory_entries[i].Characteristics);
00346         const auto import_address_table = reinterpret_cast<const IMAGE_THUNK_DATA *>(_image_base + import_directory_entries[i].FirstThunk);
00347 
00348         // The module should have already been loaded by Windows when the application was launched, so just get its handle here
00349         const auto target_base = reinterpret_cast<const BYTE *>(GetModuleHandleA(name));
00350         if (target_base == nullptr)
00351             continue; // Bail out if that is not the case to be safe
00352 
00353         for (unsigned int k = 0; import_name_table[k].u1.AddressOfData != 0; k++)
00354         {
00355             const char *import_name = nullptr;
00356 
00357             // We need to figure out the name of symbols imported by ordinal by going through the export table of the target module
00358             if (IMAGE_SNAP_BY_ORDINAL(import_name_table[k].u1.Ordinal))
00359             {
00360                 const auto target_headers = reinterpret_cast<const IMAGE_NT_HEADERS *>(target_base + reinterpret_cast<const IMAGE_DOS_HEADER *>(target_base)->e_lfanew);
00361                 const auto export_directory = reinterpret_cast<const IMAGE_EXPORT_DIRECTORY *>(target_base + target_headers->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT].VirtualAddress);
00362                 const auto export_name_strings = reinterpret_cast<const DWORD *>(target_base + export_directory->AddressOfNames);
00363                 const auto export_name_ordinals = reinterpret_cast<const WORD *>(target_base + export_directory->AddressOfNameOrdinals);
00364 
00365                 const auto ordinal = std::find(export_name_ordinals, export_name_ordinals + export_directory->NumberOfNames, IMAGE_ORDINAL(import_name_table[k].u1.Ordinal));
00366                 if (ordinal != export_name_ordinals + export_directory->NumberOfNames)
00367                     import_name = reinterpret_cast<const char *>(target_base + export_name_strings[std::distance(export_name_ordinals, ordinal)]);
00368                 else
00369                     continue; // Ignore ordinal imports for which the name could not be resolved
00370             }
00371             else
00372             {
00373                 import_name = reinterpret_cast<const IMAGE_IMPORT_BY_NAME *>(_image_base + import_name_table[k].u1.AddressOfData)->Name;
00374             }
00375 
00376             _symbols.insert({ import_name, reinterpret_cast<void *>(import_address_table[k].u1.AddressOfData) });
00377         }
00378 
00379         read_debug_info(target_base);
00380     }
00381 }
