00384 {
00385     event_handle = target_info.overlapped.hEvent = CreateEvent(nullptr, TRUE, FALSE, nullptr);
00386     if (event_handle == NULL)
00387     {
00388         print("  Error: CreateEvent failed.");
00389         return false;
