00392     DWORD size = 0;
00393     if (!ReadDirectoryChangesW(dir_handle, reinterpret_cast<FILE_NOTIFY_INFORMATION *>(target_info.p_info.data()), static_cast<DWORD>(target_info.p_info.size()), TRUE, FILE_NOTIFY_CHANGE_LAST_WRITE | FILE_NOTIFY_CHANGE_FILE_NAME, &size, &target_info.overlapped, nullptr))
00394     {
00395         print("  Error: ReadDirectoryChangesW failed.");
00396         return false;
00397     }
00398 
00399     return true;
00400 }
