00402 std::string blink::application::build_compile_command_line(const std::filesystem::path &source_file, std::filesystem::path &object_file) const
00403 {
00404     std::string cmdline;
00405 
00406     Sleep(100); // Prevent file system error in the next few code lines, TODO: figure out what causes this
00407 
00408     // Check if this source file already exists in the application in which case we can read some information from the original object file
00409     if (const auto it = _source_file_map.find(source_file);
00410         it != _source_file_map.end())
00411     {
00412         object_file = _object_files[it->second.module];
00413 
00414         // Read original object file
00415         COFF_HEADER header;
00416         const scoped_handle file = open_coff_file(object_file, header);
00417         if (file != INVALID_HANDLE_VALUE)
00418         {
00419             DWORD read = header.is_extended() ? header.bigobj.NumberOfSections : header.obj.NumberOfSections;
00420             std::vector<IMAGE_SECTION_HEADER> sections(read);
00421             ReadFile(file, sections.data(), read * sizeof(IMAGE_SECTION_HEADER), &read, nullptr);
00422 
00423             // Find first debug symbol section and read it
00424             const auto section = std::find_if(sections.begin(), sections.end(), [](const auto &s) {
00425                 return strcmp(reinterpret_cast<const char(&)[]>(s.Name), ".debug$S") == 0; });
00426             if (section != sections.end())
00427             {
00428                 std::vector<char> debug_data(section->SizeOfRawData);
00429                 SetFilePointer(file, section->PointerToRawData, nullptr, FILE_BEGIN);
00430                 ReadFile(file, debug_data.data(), section->SizeOfRawData, &read, nullptr);
00431 
00432                 // Skip header in front of CodeView records (version, ...)
00433                 stream_reader stream(std::move(debug_data));
00434                 stream.skip(4); // Skip 32-bit signature (this should be CV_SIGNATURE_C13, aka 4)
00435 
00436                 while (stream.tell() < stream.size() && cmdline.empty())
00437                 {
00438                     // CV_DebugSSubsectionHeader_t
00439                     const auto subsection_type = stream.read<uint32_t>();
00440                     const auto subsection_length = stream.read<uint32_t>();
00441                     if (subsection_type != 0xf1) // DEBUG_S_SYMBOLS
00442                     {
00443                         stream.skip(subsection_length);
00444                         stream.align(4);
00445                         continue;
00446                     }
00447 
00448                     parse_code_view_records(stream, subsection_length, [&](uint16_t tag) {
00449                         if (tag != 0x113d) // S_ENVBLOCK
00450                             return; // Skip all records that are not about the compiler environment
00451                         stream.skip(1);
00452                         while (stream.tell() < stream.size() && *stream.data() != '\0')
00453                         {
00454                             const auto key = stream.read_string();
00455                             const std::string value(stream.read_string());
00456 
00457                             if (key == "cwd")
00458                                 cmdline += "cd /D \"" + value + "\"\n";
00459                             else if (key == "cl") // Add compiler directories to path, so that 'mspdbcore.dll' is found
00460                                 cmdline += "set PATH=%PATH%;" + value + "\\..\\..\\x86;" + value + "\\..\\..\\x64\n\"" + value + "\" ";
00461                             else if (key == "cmd")
00462                                 cmdline += value;
00463                         }
00464                     });
00465 
00466                     stream.align(4); // Subsection headers are 4-byte aligned
00467                 }
00468             }
00469         }
00470     }
00471 
00472     // Fall back to default command-line if unable to extract it
00473     if (cmdline.empty())
00474     {
00475         cmdline = "cl.exe "
00476             "/nologo " // Suppress copyright message
00477             "/Z7 " // Enable COFF debug information
00478             "/MDd " // Link with 'MSVCRTD.lib'
00479             "/Od " // Disable optimizations
00480             "/EHsc " // Enable C++ exceptions
00481             "/std:c++latest " // C++ standard version
00482             "/Zc:wchar_t /Zc:forScope /Zc:inline "; // C++ language conformance
00483 
00484         cmdline = R"(cl.exe /c /ZI /JMC /nologo /W3 /WX- /diagnostics:column /sdl /Od /D _DEBUG /D _CONSOLE /D _CRT_OBSOLETE_NO_WARNINGS /D _UNICODE /D UNICODE /Gm- /EHsc /RTC1 /MDd /GS /fp:precise /Zc:wchar_t /Zc:forScope /Zc:inline /permissive- /Fo"x64\Debug\\" /Fd"x64\Debug\vc143.pdb" /external:W3 /Gd /TP /FC /errorReport:prompt )";
00485     }
00486 
00487     // Make sure to only compile and not link too
00488     //cmdline += " /c ";
00489 
00490     // Remove some arguments from the command-line since they are set to different values below
00491     const auto remove_arg = [&cmdline](std::string arg) {
00492         for (unsigned int k = 0; k < 2; ++k)
00493             if (size_t offset = cmdline.find("-/"[k] + arg); offset != std::string::npos)
00494             {
00495                 if (cmdline[offset + 1 + arg.size()] != '\"')
00496                     cmdline.erase(offset, cmdline.find(' ', offset) - offset);
00497                 else
00498                     cmdline.erase(offset, cmdline.find('\"', offset + 2 + arg.size()) + 2 - offset);
00499                 break;
00500             }
00501     };
00502 
00503     remove_arg("Fo");
00504     remove_arg("Fd"); // The program debug database is currently in use by the running application, so cannot write to it
00505     remove_arg("ZI"); // Do not create a program debug database, since all required debug information can be stored in the object file instead
00506     remove_arg("Yu"); // Disable pre-compiled headers, since the data is not accessible here
00507     remove_arg("Yc");
00508     remove_arg("JMC");
00509 
00510     // Always write to a separate object file since the original one may be in user by a debugger
00511     object_file = source_file; object_file.replace_extension("temp.obj");
00512 
00513     // Append input source file to command-line
00514     cmdline += " \"" + source_file.string() + '\"';
00515 
00516     // Append output object file to command-line
00517     cmdline += " /Fo\"" + object_file.string() + '\"';
00518 
00519     return cmdline;
00520 }
